`,a.jsx(e.p,{children:"Sened te predaje nije jak. Prenosioca Ebu Uvejsa oslabili su mnogi učenjaci. Prenosilac Ismail ibn Ebu Uvejs jeste pouzdan, ali je grešio. Predaja je, dakle, veoma slaba."}),`
